using System;using System.IO;using System.Collections.Generic;using System.Xml;using System.Xml.Serialization;
class WorldTransactions182 {
 static string path;static int checks;static void Check(bool b,string s){checks++;if(!b)throw new Exception(s);}
 static void Seed(){bool dup;Offline70Economy.Apply(path,Guid.NewGuid().ToString("N"),"fixture","empty",delegate(Offline70EconomyState s){s.Inventory.Clear();},out dup);}
 static string Bytes(){return Convert.ToBase64String(File.ReadAllBytes(path));}
 static int Main(string[] a){try{
  string dir=Path.GetFullPath(a[0]);if(dir.IndexOf(Path.Combine("build","worlddrop-research"),StringComparison.OrdinalIgnoreCase)<0)throw new Exception("Test scope");Directory.CreateDirectory(dir);path=Path.Combine(dir,"economy.xml");
  Offline70WishBoxFG84.Register();Offline70BoosterRewardsFG47.Register();Offline70BoosterOpenFG46.Register();Offline70CashPurchaseFG45.Register();Offline70NpcPurchaseFG44.Register();Offline70ItemMetadataFG.Register(Path.Combine(a[1],"item-metadata.xml"));Offline70ItemMetadataFG.Register(Path.Combine(a[1],"world-item-metadata-FG182.xml"));Offline70WorldDropsFG182.Load(Path.Combine(a[1],"world-drops-FG182.xml"));
  int quote=0;foreach(string line in File.ReadAllLines(a[2])){if(line.Length==0||line.StartsWith("level"))continue;string[] c=line.Split('\t');uint actual=Offline70WorldDropsFG182.Select(Int32.Parse(c[0]),UInt32.Parse(c[1]),UInt32.Parse(c[2]));Check(actual==UInt32.Parse(c[3]),"Original native quote mismatch "+quote);quote++;}
  Offline70ItemMetadataDocumentFG meta;using(FileStream f=File.OpenRead(Path.Combine(a[1],"world-item-metadata-FG182.xml")))meta=(Offline70ItemMetadataDocumentFG)new XmlSerializer(typeof(Offline70ItemMetadataDocumentFG)).Deserialize(f);
  int assets=0;foreach(Offline70EconomyItemDefinition item in meta.Items){Seed();bool dup;Offline70EconomyState after=Offline70Economy.Apply(path,"pickup-"+item.ItemId,"pickup","world:"+item.ItemId,delegate(Offline70EconomyState s){Offline70Economy.AddAssetItem(s,item.ItemId,1);},out dup);Check(!dup&&after.Inventory.Count==1&&after.Inventory[0].ItemId==item.ItemId&&after.Inventory[0].Quantity==1,"World item pickup");string saved=Bytes();after=Offline70Economy.Apply(path,"pickup-"+item.ItemId,"pickup","world:"+item.ItemId,delegate(Offline70EconomyState s){Offline70Economy.AddAssetItem(s,item.ItemId,1);},out dup);Check(dup&&saved==Bytes(),"Repeated pickup changed file");Check(Offline70Economy.Load(path).Inventory[0].ItemId==item.ItemId,"World item reload");File.WriteAllBytes(Path.Combine(dir,"update-"+item.ItemId+".bin"),Offline70EconomyProtocol.InventoryBody(after,false,0));File.WriteAllBytes(Path.Combine(dir,"restore-"+item.ItemId+".bin"),Offline70EconomyProtocol.InventoryBody(after,true,0));assets++;}
  Seed();bool duplicate;Offline70Economy.Apply(path,"full","fixture","full-material",delegate(Offline70EconomyState s){for(ushort n=105;n<137;n++)s.Inventory.Add(new Offline70EconomyEntry{List=0,Slot=n,ItemId=3015,Quantity=1000});for(ushort n=3;n<9;n++)s.Inventory.Add(new Offline70EconomyEntry{List=0,Slot=n,ItemId=3015,Quantity=1000});},out duplicate);string before=Bytes();try{Offline70Economy.Apply(path,"capacity","pickup","iron",delegate(Offline70EconomyState s){Offline70Economy.AddAssetItem(s,3027,1);},out duplicate);throw new Exception("Expected capacity refusal");}catch(InvalidDataException){Check(before==Bytes(),"Full bag lost item or wrote receipt");}
  Offline70Economy.Apply(path,"stack-room","fixture","room",delegate(Offline70EconomyState s){Offline70Economy.Find(s,0,105).ItemId=3027;Offline70Economy.Find(s,0,105).Quantity=999;},out duplicate);
  Offline70EconomyState result=Offline70Economy.Apply(path,"capacity","pickup","iron",delegate(Offline70EconomyState s){Offline70Economy.AddAssetItem(s,3027,1);},out duplicate);Check(!duplicate&&Offline70Economy.Find(result,0,105).Quantity==1000,"Same pending pickup recovers into existing stack");before=Bytes();Offline70Economy.Apply(path,"capacity","pickup","iron",delegate(Offline70EconomyState s){Offline70Economy.AddAssetItem(s,3027,1);},out duplicate);Check(duplicate&&Bytes()==before,"Recovered pickup duplicate");
  List<Offline70FloorDropsFG119.Reward> rewards=new List<Offline70FloorDropsFG119.Reward>();Offline70WorldDropsFG182.Append(rewards,30,3,"boss-boundary");Check(rewards.Count==0,"Boss incorrectly receives ordinary world draw");
  // Existing receipts are kept and all files are disposable test files.
  Console.WriteLine("{\"allPassed\":true,\"nativeQuoteCases\":"+quote+",\"assetCases\":"+assets+",\"checks\":"+checks+",\"releaseAllowed\":false}");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
